const input = $input.first().json;
const body = input.body || {};
const ids = body.message_ids;
if (!Array.isArray(ids)) throw new Error('Body must contain message_ids as an array');
if (ids.length > 20) throw new Error('message_ids may contain at most 20 IDs');
if (ids.length === 0) throw new Error('message_ids must contain at least one ID');
const cleaned = ids.map((id) => String(id || '').trim());
if (cleaned.some((id) => !id)) throw new Error('message_ids may not contain empty IDs');
const rawMaxChars = body.max_chars === undefined ? 1500 : Number(body.max_chars);
if (!Number.isInteger(rawMaxChars) || rawMaxChars < 1 || rawMaxChars > 8000) throw new Error('max_chars must be an integer from 1 to 8000');
return cleaned.map((message_id) => ({ json: { message_id, max_chars: rawMaxChars } }));

const decodeEntities = (value) => String(value ?? '')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');

const clean = (value) => decodeEntities(value)
  .replace(/[\u034F\u200B\u200C\u200D\u00AD\uFEFF]/g, '')
  .replace(/&(?:zwnj|zwj|shy|#8203|#8204|#8205|#173|#65279|#x200b|#x200c|#x200d|#xad|#xfeff);/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const stripHtml = (value) => clean(String(value ?? '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n')
  .replace(/<[^>]+>/g, ' '));

const extractLinks = (html) => {
  if (!html || typeof html !== 'string') return [];
  const links = [];
  const seen = new Set();
  const anchorRe = /<a\b([^>]*)>([\s\S]*?)<\/a\s*>/gi;
  let match;
  while ((match = anchorRe.exec(html)) !== null && links.length < 60) {
    const attrs = match[1] || '';
    const inner = match[2] || '';
    const hrefMatch = attrs.match(/\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/i);
    if (!hrefMatch) continue;
    const url = decodeEntities(hrefMatch[1] ?? hrefMatch[2] ?? hrefMatch[3] ?? '').trim();
    if (!url || /^(?:#|cid:|data:|javascript:|about:)/i.test(url)) continue;
    const text = stripHtml(inner);
    if (!text) continue;
    const filterText = `${text} ${url}`.toLowerCase();
    if (/unsubscribe|email[\s_-]*preferences?|manage(?:%20|\s)+(?:this(?:%20|\s)+)?(?:job(?:%20|\s)+)?alert|alert[\s_-]*settings?|notification[\s_-]*settings?|edit(?:%20|\s)+frequency|contact(?:%20|\s)+us|\bsettings?\b|\bprivacy\b|\bhelp\b/.test(filterText)) continue;
    if (/apps\.apple\.com|itunes\.apple\.com|play\.google\.com|app[\s_-]*store|google(?:%20|\s)+play|(?:download|install|get)(?:%20|\s|\w){0,24}(?:%20|\s)+app\b/.test(filterText)) continue;
    if (seen.has(url)) continue;
    seen.add(url);
    links.push({ text, url });
  }
  return links;
};

const body = $('Webhook').first().json.body || {};
const maxChars = body.max_chars === undefined ? 1500 : Number(body.max_chars);
return $input.all().map((item) => {
  const msg = item.json || {};
  const htmlBody = typeof msg.html === 'string' ? msg.html : '';
  let rawBody = htmlBody || msg.text || msg.textPlain || msg.body || msg.textAsHtml || '';
  if (typeof rawBody !== 'string') rawBody = JSON.stringify(rawBody);
  const bodyText = (/<[^>]+>/.test(rawBody) ? stripHtml(rawBody) : clean(rawBody)).slice(0, maxChars);
  return { json: { message_id: clean(msg.id || msg.messageId), body_text: bodyText, links: extractLinks(htmlBody) } };
});
